import app from 'flarum/forum/app';
import Notification from 'flarum/forum/components/Notification';
/** "Door N of <calendar> is open." Nothing about what's behind it. */
export default class DoorOpenNotification extends Notification {
  data() {
    return this.attrs.notification.content() || {};
  }
  icon() {
    return 'fas fa-door-open';
  }
  href() {
    const {
      slug
    } = this.data();
    return slug ? app.route('giveaways.advent', {
      slug
    }) : app.route('giveaways.index');
  }
  content() {
    return app.translator.trans('ernestdefoe-giveaways.forum.advent.notification', {
      day: this.data().day
    });
  }
  excerpt() {
    return this.data().title;
  }
}
flarum.reg.add('ernestdefoe-giveaways', 'forum/advent/DoorOpenNotification', DoorOpenNotification);